<script setup>
import { Link, router } from '@inertiajs/vue3';import {reactive}from'vue';import AdminLayout from '../../../Layouts/AdminLayout.vue';
const props=defineProps({words:Object,search:String,status:String});const filters=reactive({q:props.search||'',status:props.status||''});function filter(){router.get('/admin/words',filters,{preserveState:true,replace:true});}
</script>
<template><AdminLayout title="单词管理" section="内容管理 / 单词管理" description="管理单词资料、详解和发布状态。"><template #actions><Link class="btn" href="/admin/words/create">＋ 新建单词</Link></template><section class="card"><form class="filter-bar" @submit.prevent="filter"><input v-model="filters.q" class="input search" type="search" placeholder="搜索单词或释义"><select v-model="filters.status" class="select"><option value="">全部状态</option><option value="draft">草稿</option><option value="published">已发布</option></select><button class="btn secondary">筛选</button><button v-if="filters.q||filters.status" type="button" class="text-link" @click="filters.q='';filters.status='';filter()">清空</button></form><div v-if="!words.data.length" class="empty-state"><strong>{{ filters.q||filters.status?'没有匹配的单词':'还没有单词' }}</strong></div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>单词</th><th>词性</th><th>释义</th><th>状态</th><th>最后更新</th><th></th></tr></thead><tbody><tr v-for="item in words.data" :key="item.id"><td><span class="badge-id">#{{item.id}}</span></td><td><div class="table-primary">{{item.headword}}</div><div class="table-secondary">{{item.ipa}}</div></td><td>{{item.part_of_speech||'—'}}</td><td>{{item.meaning}}</td><td><span class="status" :class="item.status">{{item.status==='published'?'已发布':'草稿'}}</span></td><td>{{item.updated_at||'—'}}</td><td><Link class="text-link" :href="`/admin/words/${item.id}/edit`">编辑</Link></td></tr></tbody></table></div><div v-if="words.data.length" class="table-footer"><span>共 {{words.total}} 个</span><div class="pager"><Link v-if="words.prev_page_url" :href="words.prev_page_url">上一页</Link><span v-else class="disabled">上一页</span><span>{{words.current_page}} / {{words.last_page}}</span><Link v-if="words.next_page_url" :href="words.next_page_url">下一页</Link><span v-else class="disabled">下一页</span></div></div></section></AdminLayout></template>
